BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should be addressed to:', '["The auditor (engagement partner)", "The entity''s board of directors", "The entity''s external legal counsel", "The SEC or applicable regulatory body"]'::jsonb, 0, 'Under AU-C 580, the management representation letter is addressed to the auditor. Because the letter serves as evidence provided to the auditor from management, it is appropriately directed to the engagement partner. Choice B is incorrect because those charged with governance receive separate communications under AU-C 260, which serves a different purpose than the representation letter.', 'easy', 1),

-- Q2: easy / L1 — Oral vs. written form requirement
(1, 'Written Representations', 'Under AU-C 580, required representations obtained from management must be in what form?', '["Oral form, documented by the auditor in the working papers", "Written form, in a management representation letter", "Either oral or written form, at management''s discretion", "A sworn affidavit notarized by legal counsel"]'::jsonb, 1, 'AU-C 580 requires management representations to be obtained in written form through a management representation letter. Written representations provide more reliable evidence than oral statements and create a formal record. While oral representations may be obtained during the audit, AU-C 580 mandates that required representations be documented in a signed written letter, not merely noted in the auditor''s working papers.', 'easy', 1),

-- Q3: hard / L4 — Evaluating contradictions between representations and other evidence
(1, 'Written Representations', 'During the audit of Meridian Healthcare Corp. for December 31, 2025, the engagement team at Lawson & Blake CPAs identifies a $1.8 million receivable from a major payer whose financial condition has deteriorated significantly. Management''s representation letter states all receivables are collectible at recorded amounts, but the auditor has obtained credit reports indicating the payer may be unable to pay. The auditor should:', '["Accept management''s representation because it constitutes sufficient appropriate audit evidence on its own", "Issue a disclaimer of opinion due to the inconsistency between management''s representations and other evidence", "Reconsider the reliability of management''s representations and perform additional procedures to resolve the inconsistency", "Withdraw from the engagement because management has provided a false representation"]'::jsonb, 2, 'Under AU-C 580.A25, when written representations are inconsistent with other audit evidence, the auditor must investigate the circumstances and reconsider the reliability of the representations. The auditor should perform additional procedures to resolve the inconsistency rather than simply accepting management''s assertion. Issuing an immediate disclaimer (choice B) is premature because the auditor must first attempt to resolve the discrepancy through inquiry and additional evidence.', 'hard', 4),

-- Q4: medium / L2 — Period covered by representations (comparative statements)
(1, 'Written Representations', 'Prescott Industries engages Taylor & Mitchell CPAs to audit its December 31, 2025 financial statements. The comparative financial statements include the prior year ended December 31, 2024, which was audited by a predecessor auditor. The representation letter should cover:', '["Only the current year ended December 31, 2025", "Both the current and prior year, regardless of the predecessor auditor", "Only the period from the predecessor auditor''s report date through December 31, 2025", "All periods referenced in the financial statements, including the comparative year"]'::jsonb, 3, 'Under AU-C 580.14, written representations cover all periods referred to in the auditor''s report. When comparative statements are presented, management''s representations relate to all periods covered, ensuring complete assertion coverage. Choice A is incorrect because limiting representations to only the current year would omit relevant assertions about comparative period amounts that the auditor is associated with through the current report.', 'medium', 2),

-- Q5: easy / L1 — Form/format of the representation letter
(1, 'Written Representations', 'The management representation letter obtained under AU-C 580 is typically prepared:', '["By the entity''s external legal counsel on law firm letterhead", "By the auditor and forwarded to the SEC before report issuance", "By the entity''s internal audit department as part of its annual report", "On entity letterhead or in a format specified by the auditor"]'::jsonb, 3, 'Under AU-C 580, the management representation letter is typically prepared on the entity''s letterhead or in a letter format specified by the auditor. The letter is a management document, not an auditor or legal document. Choice A is incorrect because legal counsel provides a separate inquiry response letter under AU-C 501, which serves a different purpose than the management representation letter.', 'easy', 1),

-- Q6: hard / L4 — Evaluating whether to request entity-specific additional representations
(1, 'Written Representations', 'During the audit of Cantwell Semiconductor Inc. for December 31, 2025, the engagement partner at Graham & Patel CPAs learns that Cantwell entered into a complex revenue-sharing arrangement with a foreign distributor involving variable consideration and milestone payments. No standard representation covers this arrangement. The engagement partner should evaluate whether to:', '["Omit any representation about the arrangement because AU-C 580 only requires the standard representations", "Document the arrangement in the working papers and rely solely on substantive testing", "Disclaim an opinion because the arrangement is too complex for management to represent on", "Request an additional written representation from management specifically addressing the completeness and terms of the revenue-sharing arrangement"]'::jsonb, 3, 'Under AU-C 580.A11, the auditor may determine that representations supplementing the required representations are necessary to support other audit evidence. For complex arrangements not covered by standard representations, entity-specific additional representations are appropriate. Choice A is incorrect because AU-C 580.13 explicitly permits the auditor to request additional written representations beyond the minimum when circumstances warrant them.', 'hard', 4),

-- Q7: hard / L4 — Evaluating management competence and knowledge for representations
(1, 'Written Representations', 'While completing the audit of Stonebridge Electronics for December 31, 2025, the engagement partner at Chen & Reeves CPAs is concerned that the newly hired CFO, who started in November 2025, may lack sufficient knowledge of transactions from earlier in the fiscal year to provide meaningful representations. The engagement partner should:', '["Evaluate whether management collectively has sufficient knowledge and consider obtaining representations from other members of management who were present during the full period", "Refuse to accept the representation letter until the previous CFO co-signs it", "Automatically issue a qualified opinion because the current CFO cannot reliably represent the entire year", "Waive the representation letter requirement for the current year and rely on the prior year''s letter"]'::jsonb, 0, 'Under AU-C 580.09, the auditor requests representations from members of management with appropriate responsibilities and knowledge. When a new CFO has limited tenure, the auditor evaluates whether management collectively can provide reliable representations and may include other knowledgeable officers. Choice C is incorrect because a qualified opinion is not automatically required — the auditor must first assess whether adequate representations can be obtained from management as a whole.', 'hard', 4),

-- Q8: medium / L3 — Analyzing effect of qualifying language in representations
(1, 'Written Representations', 'The management of Ridgeline Aerospace Corp. provides a December 31, 2025 representation letter to the audit team at Weston & Fairchild CPAs, but inserts qualifying language stating, ''To the best of our knowledge and belief, except for matters we may not be aware of.'' The most likely effect on the audit is that:', '["The auditor accepts the qualified language because it is standard phrasing in all representation letters", "The auditor determines whether the qualifying language creates a scope limitation and evaluates its effect on the audit opinion", "The auditor automatically issues an adverse opinion due to management''s refusal to provide unqualified representations", "The auditor revises the engagement letter to remove the requirement for written representations"]'::jsonb, 1, 'Under AU-C 580.A27, the auditor evaluates the effect of qualifying language in representations. While ''to the best of our knowledge and belief'' is acceptable for belief-based matters, adding ''except for matters we may not be aware of'' could negate the representation. The auditor must assess whether this creates a scope limitation. Choice A is incorrect because the additional qualifying language fundamentally undermines the assurance the representation is intended to provide.', 'medium', 3),

-- Q9: medium / L2 — Representation about accounting policy appropriateness
(1, 'Written Representations', 'Oakmont Financial Services engages Barrett & Lang CPAs for the December 31, 2025 audit. During fieldwork, the engagement team discovers that Oakmont adopted a new revenue recognition method for certain advisory fees. The engagement partner requests a representation about accounting policies. Management should represent that:', '["The auditor has approved all accounting policies used in preparing the financial statements", "The accounting policies were selected by the board of directors without management involvement", "The selection and application of accounting policies are appropriate for the entity''s financial statements", "All accounting policies used are identical to those used by the entity''s competitors"]'::jsonb, 2, 'Under AU-C 580.11, management provides written representations that it has fulfilled its responsibility for the preparation and fair presentation of the financial statements, including the appropriate selection and application of accounting policies. Choice A is incorrect because the auditor does not approve accounting policies — management is responsible for selecting appropriate policies, and the auditor evaluates whether those selections conform to the applicable financial reporting framework.', 'medium', 2),

-- Q10: easy / L1 — Management's responsibility for internal control
(1, 'Written Representations', 'Under AU-C 580, management is asked to represent its responsibility for which of the following?', '["The design, implementation, and maintenance of internal control relevant to financial statement preparation", "Selecting the audit firm and negotiating the audit fee", "Ensuring the auditor has reviewed every transaction during the period", "Preparing the auditor''s report on the financial statements"]'::jsonb, 0, 'AU-C 580.10 requires management to acknowledge its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of the financial statements, regardless of entity size. Choice D is incorrect because the auditor''s report is the auditor''s responsibility, not management''s — the representation letter addresses management''s own responsibilities, not those belonging to the auditor.', 'easy', 1),

-- Q11: easy / L2 — Distinguishing the representation letter from the engagement letter
(1, 'Written Representations', 'During the audit of Lakewood Properties LLC for December 31, 2025, a new staff auditor at Harper & Associates asks the senior auditor how the management representation letter differs from the engagement letter. The key distinction is that the representation letter:', '["Establishes the terms and scope of the audit engagement before fieldwork begins", "Is prepared by the auditor and signed by management to acknowledge audit procedures performed", "Is signed by the entity''s external legal counsel to confirm compliance with applicable law", "Is obtained near the end of the audit and contains management''s assertions about the financial statements"]'::jsonb, 3, 'Under AU-C 580, the management representation letter is obtained near the end of the audit and contains management''s written assertions about matters relevant to the financial statements. The engagement letter (AU-C 210) establishes the terms of the engagement before the audit begins. Choice A is incorrect because it describes the engagement letter, not the representation letter — these two documents serve fundamentally different purposes at different stages of the engagement.', 'easy', 2),

-- Q12: medium / L3 — Analyzing effect of a missing specific representation
(1, 'Written Representations', 'During the audit of Evergreen Logistics Corp. for December 31, 2025, the engagement partner at Mason & Drake CPAs requests that management include a representation about the completeness of related party disclosures. Management provides the letter but omits this specific representation, claiming the auditor already tested related parties. The most likely effect is that the auditor:', '["Accepts the letter because the auditor''s own procedures are sufficient to compensate for the missing representation", "Discusses the omission with management and evaluates whether the absence constitutes a scope limitation", "Automatically issues a disclaimer of opinion for any missing representation beyond the minimum requirements", "Files the incomplete letter and notes the omission in the working papers without further action"]'::jsonb, 1, 'Under AU-C 580.20, if management does not provide one or more of the requested written representations, the auditor must discuss the matter with management, evaluate the effect on the audit, and determine whether a scope limitation exists. Written representations complement the auditor''s procedures. Choice A is incorrect because audit procedures cannot fully replace management''s affirmative written acknowledgment of completeness — representations serve a distinct evidentiary purpose.', 'medium', 3),

-- Q13: easy / L1 — Representation about uncorrected misstatements
(1, 'Written Representations', 'Under AU-C 580, the management representation letter includes a representation about uncorrected misstatements. Specifically, management acknowledges that:', '["No misstatements of any amount exist in the financial statements", "All misstatements identified by the auditor have been corrected before the report date", "The effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements", "The auditor is responsible for identifying and correcting all material misstatements"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that the effects of uncorrected misstatements aggregated by the auditor are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached to the letter. Choice A is incorrect because AU-C 580 does not require management to assert that no misstatements exist — rather, it requires acknowledgment that any uncorrected items are immaterial.', 'easy', 1),

-- Q14: easy / L1 — Representation about completeness of litigation and claims
(1, 'Written Representations', 'Under AU-C 580, what must management represent regarding litigation and claims?', '["The entity will prevail in all pending litigation matters", "The entity has no litigation or claims of any kind", "All known actual or possible litigation and claims have been disclosed to the auditor", "The entity''s legal counsel has confirmed that all claims will be resolved favorably"]'::jsonb, 2, 'AU-C 580 requires management to represent that all known actual or possible litigation and claims whose effects should be considered in the financial statements have been disclosed to the auditor. This ensures complete information for evaluating contingent liabilities under ASC 450. Choice A is incorrect because management cannot guarantee litigation outcomes — the representation concerns disclosure of known matters, not predictions about resolution.', 'easy', 1),

-- Q15: hard / L4 — Evaluating whether disclaimer eliminates need for representations
(1, 'Written Representations', 'The engagement partner at Linden & Holt CPAs is preparing a disclaimer of opinion on Crossfield Manufacturing''s December 31, 2025 financial statements due to a significant scope limitation. A staff auditor suggests that since the firm is disclaiming, the management representation letter is unnecessary. The engagement partner should:', '["Still obtain the management representation letter because written representations are required regardless of the opinion type issued", "Agree with the staff auditor because a disclaimer means the auditor is not expressing an opinion", "Issue the disclaimer without the letter but document the rationale in the working papers", "Request only a partial representation letter covering matters not affected by the scope limitation"]'::jsonb, 0, 'Under AU-C 580.09, written representations are required in all audits, regardless of the opinion type. Even when issuing a disclaimer, the auditor obtains the representation letter because it provides evidence about management''s acknowledgment of its responsibilities. Choice B is incorrect because while a disclaimer means the auditor cannot express an opinion, the requirement for written representations is independent of the opinion type.', 'hard', 4),

-- Q16: medium / L3 — Analyzing the relationship between representations and professional skepticism
(1, 'Written Representations', 'During the audit of Pinnacle Data Systems for December 31, 2025, the engagement team at Aldridge & Foster CPAs receives a comprehensive management representation letter. A senior auditor asks whether professional skepticism still applies to matters covered by the letter. The correct analysis is that:', '["Professional skepticism must be maintained because written representations do not relieve the auditor of the responsibility to obtain sufficient appropriate audit evidence", "Professional skepticism is reduced for matters explicitly covered by management''s written representations", "Professional skepticism applies only to matters where management''s representations conflict with other evidence", "Written representations automatically satisfy the auditor''s evidence requirements for the represented matters"]'::jsonb, 0, 'Under AU-C 580.A1, written representations are an important source of audit evidence but do not substitute for other evidence the auditor expects to be available. The auditor must maintain professional skepticism (AU-C 200.17) throughout the audit regardless of representations received. Choice B is incorrect because written representations do not diminish the auditor''s obligation to exercise skepticism — representations complement, not replace, corroborative evidence.', 'medium', 3),

-- Q17: hard / L4 — Evaluating impact of discovering prior-period representation was false
(1, 'Written Representations', 'After issuing the audit report for Redwood Partners'' December 31, 2025 financial statements, the engagement partner at Sullivan & Grant CPAs discovers that a representation in the prior-year 2024 letter was materially false — management had concealed a significant related party transaction. The engagement partner should:', '["Take no action because the prior-year audit is complete and cannot be revisited", "Evaluate the effect on the prior-year audit, consider communicating with those charged with governance, and determine whether action regarding the previously issued report is necessary", "Immediately reissue the 2024 audit report with a qualified opinion without further investigation", "Notify law enforcement because management provided a false written statement"]'::jsonb, 1, 'Under AU-C 560.14 and AU-C 580, when the auditor discovers that a prior-period representation was materially false, the auditor must evaluate the effect on the previously issued report and related audit evidence. This includes communicating with those charged with governance and considering the need to revise the prior opinion. Choice A is incorrect because discovery of a materially false representation triggers an active obligation to evaluate and respond, regardless of whether the prior engagement is complete.', 'hard', 4),

-- Q18: medium / L2 — Representation about subsequent events in the letter
(1, 'Written Representations', 'Granville Corp.''s December 31, 2025 audit is performed by Fleming & Associates CPAs, with the auditor''s report dated March 15, 2026. In the management representation letter, management should represent that all events occurring between December 31, 2025 and what date that require recognition or disclosure have been properly addressed?', '["December 31, 2025, because representations relate only to the balance sheet date", "February 28, 2026, the date fieldwork was substantially completed", "March 15, 2026, the date of the auditor''s report", "The date the financial statements are issued to third parties"]'::jsonb, 2, 'Under AU-C 580.15, the representation letter is dated as of the date of the auditor''s report. Management''s representations about subsequent events cover events through that date, ensuring all events requiring recognition or disclosure under AU-C 560 have been properly addressed. Choice A is incorrect because limiting the subsequent events representation to the balance sheet date would leave a gap in coverage between year-end and the report date.', 'medium', 2),

-- Q19: medium / L2 — Representation about access to records and personnel
(1, 'Written Representations', 'Birchmont Industries engages Crawford & Lee CPAs for the December 31, 2025 audit. The engagement partner asks what the management representation letter should state regarding the auditor''s access during the engagement. Management should represent that:', '["The auditor was permitted to attend all board meetings during the year", "The auditor independently verified all electronic records without management assistance", "Management selected which records the auditor was permitted to examine", "All financial records and related data were made available to the auditor, and all transactions have been recorded"]'::jsonb, 3, 'Under AU-C 580.11, management represents that it has provided the auditor with access to all information relevant to the preparation of the financial statements and that all transactions have been recorded and reflected in the financial statements. This supports the completeness assertion. Choice C is incorrect because management restricting which records the auditor can examine would constitute a scope limitation, not an appropriate representation under AU-C 580.', 'medium', 2),

-- Q20: medium / L3 — Analyzing whether non-management personnel can provide representations
(1, 'Written Representations', 'During the audit of Crestview Manufacturing for December 31, 2025, the engagement partner at Morrison & Blake CPAs considers requesting written representations from the head of information technology regarding the completeness of system change logs. The correct analysis is that:', '["Additional representations from knowledgeable personnel may be appropriate when specific operational matters fall outside senior management''s direct knowledge", "Only the CEO and CFO may provide representations, and no other personnel may sign supplementary representations", "Representations from non-management employees automatically carry greater evidentiary weight than management representations", "The IT department head must sign the management representation letter in place of the CFO for technology-related matters"]'::jsonb, 0, 'Under AU-C 580.09, the auditor requests written representations from management with appropriate responsibilities and knowledge. When specific operational matters such as IT system changes fall outside senior management''s direct knowledge, the auditor may request representations from other knowledgeable personnel. Choice B is incorrect because while the CEO and CFO typically sign the primary letter, AU-C 580 does not prohibit obtaining supplementary representations from other informed individuals.', 'medium', 3),

-- Q21: hard / L3 — Analyzing impact of management turnover on representation letter signers
(1, 'Written Representations', 'Whitmore Industries'' December 31, 2025 audit is being completed by Parker & Associates CPAs. The CEO who served throughout 2025 resigned on February 15, 2026, and a new CEO was appointed on March 1, 2026. The auditor''s report is dated March 10, 2026. The engagement partner must analyze the most appropriate approach to the representation letter signers:', '["Delay the auditor''s report until the new CEO has been in office for at least 30 days", "Obtain the letter signed by the new CEO and CFO, considering whether the new CEO has sufficient knowledge and supplementing with representations from other knowledgeable personnel if necessary", "Request the former CEO to sign the representation letter because that person has direct knowledge of the full fiscal year", "Issue a disclaimer of opinion because a change in CEO creates an inherent scope limitation"]'::jsonb, 1, 'Under AU-C 580.09 and .A8, the representation letter is signed by current management as of the report date. When a new CEO has limited tenure, the auditor evaluates whether that person has sufficient knowledge and may obtain supplementary representations from individuals who were present during the period. Choice C is incorrect because the former CEO no longer holds the position and cannot represent current management — the current management team is responsible for representations as of the report date.', 'hard', 3),

-- Q22: medium / L2 — Representation about estimates and significant assumptions
(1, 'Written Representations', 'During the December 31, 2025 audit of Ashworth Capital Group, the engagement team at Dixon & Pratt CPAs identifies significant Level 3 fair value measurements requiring complex valuation estimates. The engagement partner requests a representation about estimates. Management should represent that:', '["Significant assumptions used in making accounting estimates are reasonable in the circumstances", "The auditor has independently verified and approved all estimates in the financial statements", "No accounting estimates were required in the preparation of the financial statements", "Estimates must equal actual future results within a 5% tolerance to be acceptable"]'::jsonb, 0, 'Under AU-C 580.11, management represents that significant assumptions used in making accounting estimates, including fair value measurements, are reasonable. This representation supports the auditor''s evaluation of estimates under AU-C 540. Choice D is incorrect because estimates inherently involve measurement uncertainty — management cannot assert that estimates will equal actual results, and reasonableness of assumptions is the appropriate standard, not precision of outcomes.', 'medium', 2),

-- Q23: medium / L2 — Representation about going concern plans and intentions
(1, 'Written Representations', 'Trenton Holdings LLC is audited by Caldwell & Pierce CPAs for the year ended December 31, 2025. During planning, the auditor identified indicators of going concern uncertainty. The engagement partner requests a specific representation regarding going concern. Management should represent:', '["The entity will continue operations for at least five years beyond the report date", "The auditor has independently confirmed the entity''s ability to continue as a going concern", "The entity''s creditors have agreed to forgive all outstanding debts", "Its plans and intentions for addressing conditions that raise substantial doubt about the entity''s ability to continue as a going concern"]'::jsonb, 3, 'Under AU-C 580 and AU-C 570, when going concern uncertainty exists, the auditor requests that management represent its plans and intentions relevant to the entity''s ability to continue as a going concern, such as asset dispositions, debt restructuring, or cost reductions. Choice A is incorrect because management cannot guarantee future operations for any specific period — the representation addresses management''s plans, not a guarantee of survival.', 'medium', 2),

-- Q24: medium / L3 — Analyzing whether representations replace confirmation procedures
(1, 'Written Representations', 'During the audit of Clearfield Retail Group for December 31, 2025, the engagement team at Novak & Sterling CPAs receives management''s representation that accounts receivable balances are valid and collectible. A staff auditor asks whether this representation eliminates the need to send receivable confirmations. The correct analysis is that:', '["Management''s representation does not substitute for confirmation procedures because written representations are not a replacement for other audit evidence the auditor expects to be available", "Management''s representation eliminates the need for confirmations when the risk of material misstatement is low", "The auditor may skip confirmations if management provides a detailed aged schedule with the representation letter", "Confirmations are only required when management refuses to provide a receivable representation"]'::jsonb, 0, 'Under AU-C 580.A2, written representations are necessary audit evidence but do not provide sufficient appropriate evidence on their own. Confirmation procedures (AU-C 505) provide independent external evidence that complements management''s representations. Choice B is incorrect because the decision to send confirmations is based on risk assessment and audit strategy, not on whether management has provided representations — even at low risk, representations do not eliminate the need for corroborative evidence.', 'medium', 3),

-- Q25: medium / L2 — Representation about compliance with laws and regulations
(1, 'Written Representations', 'Hargrove Pharmaceuticals Inc. is audited by Kessler & Owens CPAs for the year ended December 31, 2025. The engagement partner asks what representation management should provide regarding compliance with laws and regulations. Management should represent that:', '["The auditor has tested compliance with all applicable laws and regulations", "All instances of identified or suspected noncompliance whose effects should be considered in the financial statements have been disclosed to the auditor", "The entity has never been subject to any regulatory investigation or enforcement action", "Compliance with laws is solely the responsibility of the entity''s external legal counsel"]'::jsonb, 1, 'Under AU-C 580.11, management represents that all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements have been disclosed to the auditor. This supports the auditor''s responsibilities under AU-C 250. Choice A is incorrect because compliance testing is not the auditor''s responsibility in a financial statement audit — the representation concerns disclosure of known noncompliance.', 'medium', 2),

-- Q26: easy / L1 — Acceptable form of a written representation
(1, 'Written Representations', 'Under AU-C 580, which of the following is an acceptable form of a written representation from management?', '["An oral statement made during a management interview and noted by the auditor", "A verbal confirmation during the exit conference with the board", "A letter on entity letterhead signed by the CEO and CFO", "An unsigned email from the controller summarizing financial results"]'::jsonb, 2, 'AU-C 580 requires written representations in the form of a representation letter addressed to the auditor and signed by appropriate members of management. A signed letter on entity letterhead meets this requirement. Choice A is incorrect because oral statements, even when documented in the auditor''s working papers, do not satisfy the written representation requirement — AU-C 580 specifically requires a signed written communication from management.', 'easy', 1),

-- Q27: easy / L1 — Definition of written representations
(1, 'Written Representations', 'Under AU-C 580, written representations are best defined as:', '["Statements prepared by the auditor and approved by management confirming the audit scope", "Written statements by management provided to the auditor to confirm certain matters or support other audit evidence", "Legal opinions from the entity''s attorneys regarding pending litigation", "Internal audit reports submitted to the engagement partner for review"]'::jsonb, 1, 'AU-C 580.07 defines written representations as written statements by management provided to the auditor to confirm certain matters or to support other audit evidence. They are a distinct form of audit evidence addressing management''s responsibilities and assertions. Choice C is incorrect because legal opinions from attorneys (AU-C 501) serve a separate purpose related to litigation and claims — they are not the management representation letter required under AU-C 580.', 'easy', 1),

-- Q28: medium / L2 — Representation about side agreements and undisclosed arrangements
(1, 'Written Representations', 'During the audit of Highland Properties Corp. for December 31, 2025, the engagement team at Cooper & Walsh CPAs discovers references in board minutes to a verbal agreement with a major tenant regarding rent concessions not reflected in the lease file. The auditor should request a representation from management regarding:', '["Whether the board minutes are accurate, since verbal agreements have no financial statement effect", "The engagement partner''s approval of the verbal agreement for accounting purposes", "The completeness of all agreements, including side agreements, that may affect the financial statements", "The tenant''s creditworthiness and ability to pay rent under the original lease terms"]'::jsonb, 2, 'Under AU-C 580.11, management represents that all agreements and arrangements that may affect the financial statements have been disclosed, including side agreements and verbal understandings. Undisclosed side agreements can result in unrecorded liabilities or misstated revenues. Choice A is incorrect because verbal agreements can have significant financial statement effects — rent concessions may require adjustment to revenue recognition or lease accounting under ASC 842.', 'medium', 2),

-- Q29: medium / L3 — Analyzing representations about guarantees and commitments
(1, 'Written Representations', 'The engagement team at Harmon & Price CPAs is auditing Westbrook Industries for December 31, 2025. During inquiry procedures, the auditor learns that Westbrook provided a $3 million guarantee on a subsidiary''s bank loan that is not disclosed in the financial statement notes. When analyzing the implications for the representation letter, the most important consideration is that:', '["The undisclosed guarantee indicates a potential gap between management''s representations about completeness and actual financial statement disclosures, warranting further investigation", "Financial commitments under $5 million are immaterial and need not be disclosed or represented by management", "The obligation is the subsidiary''s responsibility and does not require disclosure in the parent''s representation letter", "Management''s verbal acknowledgment of the commitment during fieldwork satisfies the representation requirement"]'::jsonb, 0, 'Under AU-C 580.11, management represents the completeness of information provided, including guarantees and commitments. Discovery of an undisclosed $3 million guarantee suggests that prior representations about completeness may be incomplete, requiring the auditor to investigate and obtain a specific written representation. Choice D is incorrect because verbal acknowledgment does not satisfy the written representation requirement under AU-C 580 — formal written confirmation and appropriate disclosure are required.', 'medium', 3),

-- Q30: medium / L3 — Analyzing when management's knowledge limitation affects representation reliability
(1, 'Written Representations', 'During the December 31, 2025 audit of Briarwood Corp., the engagement team at Thornton & Associates CPAs requests a representation about the completeness of environmental liabilities. Management states it has no specialized knowledge of environmental regulations and cannot provide an informed representation on this matter. The auditor should analyze this situation by considering that:', '["The auditor should delete the environmental liability representation from the letter because management cannot represent beyond its expertise", "Management''s inability to provide an informed representation may indicate a need for the entity to engage a specialist and may affect the sufficiency of audit evidence", "Environmental liabilities are always immaterial and never require a specific representation", "The auditor should provide management with the correct environmental liability amounts to include in the letter"]'::jsonb, 1, 'Under AU-C 580.A7, when management indicates it lacks knowledge about specific matters, the auditor considers whether a management specialist is needed (AU-C 500) and evaluates the effect on the sufficiency and appropriateness of audit evidence. Management''s inability to represent may indicate inadequate internal expertise for financial reporting. Choice A is incorrect because removing the representation does not resolve the underlying issue — if environmental liabilities could be material, the auditor needs sufficient evidence regardless.', 'medium', 3)
;

COMMIT;
